import AppKit

/// Every save of the package announced to the cache ledger, so no marker,
/// waveform or voice file lands between the save's listing and its swap
/// (`MediaImporter.CacheLedger`, `MediaCacheLedger.swift`).
///
/// This one override is enough: ⌘S, Save As, autosave and `save_project`
/// all funnel through `save(to:ofType:for:completionHandler:)`, and NSDocument
/// lists the package for its lazy `cache/` wrapper and swaps the new package
/// in before that completion runs. `saveBegan` waits for a publication
/// already being written; `saveEnded` runs before the caller's handler.
extension ProjectDocument {
    override func save(
        to url: URL, ofType typeName: String, for saveOperation: NSDocument.SaveOperationType,
        completionHandler: @escaping ((any Error)?) -> Void
    ) {
        guard let directory = intendedCacheDirectory else {
            super.save(to: url, ofType: typeName, for: saveOperation,
                       completionHandler: completionHandler)
            return
        }
        let save = MediaImporter.CacheLedger.shared.saveBegan(cacheDir: directory)
        super.save(to: url, ofType: typeName, for: saveOperation) { error in
            MediaImporter.CacheLedger.shared.saveEnded(cacheDir: directory, save: save)
            completionHandler(error)
        }
    }
}
import AppKit

/// The document's title as a file STEM — what a save panel puts its own
/// extension after. Three panels want it (Export…, Save Frame…, Export
/// Captions…) and all three used to derive it with a bare
/// `deletingPathExtension` over `displayName`, which takes whatever follows
/// the last dot: an untitled document opened from `Board v1.2.mov` is titled
/// "Board v1.2" (`defaultDraftName()` strips the movie's extension and
/// nothing else) and was offered as `Board v1.mp4`, `Board v1 ….png` and
/// `Board v1.srt`. Measured: `("Board v1.2" as NSString).deletingPathExtension`
/// is "Board v1".
///
/// **The known set here is `{framejob}` and nothing else** — not
/// `CaptionExporter.knownExtensions`' `{srt, vtt}` and not `FrameWriter`'s
/// image spellings, however alike the lines look. Those two strip a suffix
/// their own popup put on a name; this strips the DOCUMENT's own extension
/// off a title-bar name, and the only extension a title bar can carry is the
/// package's, shown or hidden as Finder's preference and the file's own flag
/// decide: a saved `Board v1.2.framejob` reads as "Board v1.2.framejob" or as
/// "Board v1.2" and must come back as "Board v1.2" from both. A caption set
/// here would turn the first into `Board v1.2.framejob.srt`, and a document
/// somebody has literally named `talk.srt` keeps its suffix and is offered
/// `talk.srt.srt` — the honest answer for a pathological name, and the file
/// `AgentServer.captionDestinationURL` writes for that path (`srt` is replaceable
/// there, so over MCP it is `talk.srt`).
///
/// It is an extension in its own file because `ProjectDocument.swift` is over
/// the ~600-line cap and should not take on code, and a pure function because
/// a save panel is reachable by no proof this project can write —
/// `tools/proof/remaining_probe.py` compiles `app/Sources` and runs a table
/// of names through `displayStem(of:)` instead.
extension ProjectDocument {

    /// What the title bar says for a document with no name yet. It is
    /// `defaultDraftName()`'s own fallback spelled again, because
    /// `displayName` is declared implicitly unwrapped — AppKit's header
    /// leaves it unannotated, so Swift reads `String!` and a nil is possible
    /// in principle before AppKit has named the document — and every panel
    /// needs SOME stem to put an extension after. The two spellings must
    /// agree, and the literal stands in `ProjectDocument.swift` too rather
    /// than that file taking on a reference to this one; the probe reads
    /// both and pins them equal.
    static let untitledDisplayName = "Untitled Project"

    /// `name` with a trailing `.framejob` removed, compared lower-cased —
    /// `destinationURL` compares its suffix lower-cased, and Finder lets a
    /// package be renamed `X.FRAMEJOB` — and nothing else removed. Foundation
    /// reads no extension off a dot-leading name (`.framejob` comes back as
    /// `.framejob`, measured), so the empty-stem fallback below is reached by
    /// no input this session could construct; it stays because a stem of
    /// nothing is the one answer a panel cannot use.
    static func displayStem(of name: String) -> String {
        let suffix = (name as NSString).pathExtension.lowercased()
        guard suffix == projectFileExtension else { return name }
        let stem = (name as NSString).deletingPathExtension
        return stem.isEmpty ? name : stem
    }

    /// The stem of THIS document's title, over `displayName`'s fallback.
    var displayStem: String {
        Self.displayStem(of: displayName ?? Self.untitledDisplayName)
    }
}
import Foundation

/// The open-time repairs of a project's media, after `project.json` is read
/// and before the document is shown: the re-anchor of consolidated media
/// (`ProjectDocument.reanchoringConsolidatedMedia`) and, here, the re-copy
/// of a WebM or Matroska copy that is gone (spec §11 #228-O, O13 and Q3).
///
/// Neither is an edit. Both run where `readPackage` runs — on
/// NSDocumentController's read queue for a person's File ▸ Open, on the
/// lane's thread inside `withoutAsking` for an agent's `open_project` (spec
/// §11 #231), on the main thread for a read AppKit runs there — before the
/// document exists as far as AppKit is concerned, so they register no undo
/// step, dirty nothing and show no alert; whatever save comes next writes
/// the new paths out.
extension ProjectDocument {

    /// `readPackage`'s repairs, in order: the re-anchor first, so a
    /// consolidated copy found in the package's `media/` is never copied
    /// again, then the re-copy.
    static func repairingMedia(_ project: ReelProject, package: URL) -> ReelProject {
        let anchored = reanchoringConsolidatedMedia(project, package: package)
        return recopyingMissingCopies(anchored)
    }

    /// Copies again every WebM or Matroska copy that is gone, from its
    /// original, and points the media at the new copy with its probe.
    ///
    /// A media is copied again when all four hold: its copy is gone —
    /// `mediaURL(for:)` resolves nothing, or resolves inside the Trash
    /// (`trashed`), where Finder's delete moves the copy and its bookmark
    /// follows it; it has an `original`; the original resolves; and the
    /// original is still a Matroska file. The copy is the built-in one only
    /// (`MediaImporter.probeBuiltInCopy`): never ffmpeg, never a question.
    /// The Trash counts as gone HERE only; every other reader of
    /// `mediaURL(for:)` still plays a copy from the Trash.
    ///
    /// Each copy shows #228-P's window after 1 s through `watch`, except on
    /// the main thread, where a window could not be shown, and inside
    /// `withoutAsking`, an agent's `open_project` (MC-5, #231): no watch is
    /// passed there. Copies run one at a time (`ContainerRewrap.assist`'s
    /// lock). A Cancel or any failure skips that media (Q3): a missing copy
    /// stays missing, with the slate, the badge and Relink…, and the next
    /// open tries again; a copy in the Trash keeps its path and bookmark.
    ///
    /// `trashed` is the probe's seam, so the Trash case is proved without
    /// touching the real Trash; the app passes none.
    static func recopyingMissingCopies(
        _ project: ReelProject, watch: RewrapWatch? = RewrapProgressWindowController.watch,
        trashed: (URL) -> Bool = isTrashed
    ) -> ReelProject {
        let shown = Thread.isMainThread || MediaImporter.isWithoutAsking ? nil : watch
        var ops: [ReelOp] = []
        for media in project.snapshot.media where media.original != nil {
            let copy = mediaURL(for: media)
            guard copy == nil || copy.map(trashed) == true else { continue }
            guard let source = originalURL(for: media), ContainerRewrap.isMatroska(source) else {
                continue
            }
            guard let descriptor = try? MediaImporter.probeBuiltInCopy(of: source, watch: shown)
            else { continue }
            ops.append(
                .relinkMedia(
                    media: media.id, path: descriptor.path, bookmark: descriptor.bookmark,
                    probe: descriptor))
        }
        guard !ops.isEmpty else { return project }
        // Only `.applied` is a repair; both other arms leave it as opened.
        return (try? project.applying(ops)).project ?? project
    }
}
import AppKit

/// The app's document controller: it knows which paths AppKit's own open is
/// reading (spec §11 #234).
///
/// **Why it exists.** A document added for a URL while AppKit is still
/// reading that URL is not seen when the read ends, and AppKit adds a second
/// document at the path. An agent's `open_project` reads on the lane's
/// thread and adds its document itself (spec §11 #231), so without this it
/// could add one while a person's File ▸ Open, Finder double-click, Recent
/// row or drop of the same file was still reading, or a person's open could
/// begin and end inside the agent's own read. `AgentServer.openProject` asks
/// `isOpening` in each of its two main-thread steps and waits for the
/// person's open; `refuseHeldPath` refuses a write to a path being opened.
///
/// **What is counted.** The two public asynchronous opens, which every door
/// AppKit has reaches (spec §11 #234 lists them): one is added to the
/// path's count on the main thread before `super`, and taken off in the
/// completion handler, which AppKit calls on main after it has added the
/// document, before the caller's handler runs. A reopen with no URL (an
/// untitled document restored) holds no path and is not counted.
///
/// **A `.fjgraphic` is not a project** (spec §11 G-47 (a)): an open of one —
/// a Finder double-click, Open With, a Dock drop, a browser's download — is
/// handed to `GraphicImportSheetController.open(packageAt:)` and answers no
/// document and no error; it is not counted. `whenSettled` is that door's
/// wait for launch and restoration (G-47 (b)): no open or reopen in flight,
/// an untitled project's reopen included.
///
/// `main.swift` makes the one instance before anything else can make an
/// `NSDocumentController`: the first one instantiated is `.shared`. No other
/// product file instantiates it. A proof probe compiles every source but
/// `main.swift` and installs a controller of its own first, and there
/// `isOpening` answers false.
class ProjectDocumentController: NSDocumentController {

    /// Opens in flight, by `AgentServer.canonical` path. Main only.
    private var opening: [String: Int] = [:]
    /// Reopens of an untitled project in flight, and what waits for none of either. Main only.
    private var untitledReopens = 0
    private var settledWaiters: [() -> Void] = []

    override init() {
        super.init()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("ProjectDocumentController does not support NSCoder")
    }

    // MARK: - Launch

    /// Makes the app's controller. Called once, from `main.swift`, before
    /// `NSApplicationMain`.
    static func install() {
        let controller = ProjectDocumentController()
        if NSDocumentController.shared !== controller {
            NSLog("Frame Job: %@", "a document controller existed before ProjectDocumentController "
                + "was installed, so an open in flight is not counted (spec §11 #234)")
        }
    }

    /// The startup complaint when the shared controller is not this class
    /// (the `Frame Job: ` prefix every MCP proof requires absent).
    static func complainUnlessShared() {
        guard !(NSDocumentController.shared is ProjectDocumentController) else { return }
        NSLog("Frame Job: %@", "the shared document controller is not ProjectDocumentController, "
            + "so open_project cannot see a window's open in flight (spec §11 #234)")
    }

    // MARK: - What is being opened

    /// Whether AppKit's own open of `url` is in flight. Main only. False
    /// when the shared controller is not this class.
    static func isOpening(_ url: URL) -> Bool {
        guard let controller = NSDocumentController.shared as? ProjectDocumentController
        else { return false }
        return controller.opens(of: url) > 0
    }

    /// How many of AppKit's opens of `url` are in flight. Main only.
    func opens(of url: URL) -> Int {
        opening[AgentServer.canonical(url.path)] ?? 0
    }

    private func began(_ url: URL) -> String {
        let key = AgentServer.canonical(url.path)
        opening[key, default: 0] += 1
        return key
    }

    private func ended(_ key: String) {
        let left = (opening[key] ?? 1) - 1
        opening[key] = left > 0 ? left : nil
        fireIfSettled()
    }

    // MARK: - Settled

    /// Runs `body` on main once no open or reopen is in flight, a main-queue turn after the
    /// last ends so AppKit has made its window — never before `applicationDidFinishLaunching`
    /// (spec §11 G-47 (b)). The next turn when the shared controller is not this class. Main.
    static func whenSettled(_ body: @escaping () -> Void) {
        guard let controller = NSDocumentController.shared as? ProjectDocumentController else {
            DispatchQueue.main.async(execute: body)
            return
        }
        controller.settledWaiters.append(body)
        controller.fireIfSettled()
    }

    private var isSettled: Bool { opening.isEmpty && untitledReopens == 0 }

    private func fireIfSettled() {
        guard isSettled, !settledWaiters.isEmpty else { return }
        DispatchQueue.main.async { [weak self] in
            guard let self, self.isSettled else { return }
            let waiting = self.settledWaiters
            self.settledWaiters = []
            for body in waiting { body() }
        }
    }

    // MARK: - The two public opens

    override func openDocument(
        withContentsOf url: URL, display displayDocument: Bool,
        completionHandler: @escaping (NSDocument?, Bool, (any Error)?) -> Void
    ) {
        if url.pathExtension.lowercased() == GraphicPackage.fileExtension {
            GraphicImportSheetController.open(packageAt: url)
            completionHandler(nil, false, nil)
            return
        }
        let key = began(url)
        super.openDocument(withContentsOf: url, display: displayDocument) {
            [weak self] document, wasOpen, error in
            self?.ended(key)
            completionHandler(document, wasOpen, error)
        }
    }

    override func reopenDocument(
        for urlOrNil: URL?, withContentsOf contentsURL: URL, display displayDocument: Bool,
        completionHandler: @escaping (NSDocument?, Bool, (any Error)?) -> Void
    ) {
        guard let url = urlOrNil else {
            untitledReopens += 1
            super.reopenDocument(
                for: urlOrNil, withContentsOf: contentsURL, display: displayDocument
            ) { [weak self] document, wasOpen, error in
                self?.untitledReopens -= 1
                self?.fireIfSettled()
                completionHandler(document, wasOpen, error)
            }
            return
        }
        let key = began(url)
        super.reopenDocument(for: url, withContentsOf: contentsURL, display: displayDocument) {
            [weak self] document, wasOpen, error in
            self?.ended(key)
            completionHandler(document, wasOpen, error)
        }
    }
}

