private func addressed(_ ops: [ReelOp]) -> [ReelOp] {
    guard let nest = scope else { return ops }
    return ops.map { $0.isDocumentLevel || $0.scope != nil ? $0 : $0.scoped(nest) }
}

/// Applies one op as one undo step.
func applyEdit(_ actionName: String, _ op: ReelOp) {
    applyEdit(actionName, [op])
}

/// Applies a sequence of ops as ONE undo step — a compound gesture (freeze
/// frame, a multi-file import); what each answer does is `commitEdit`'s.
func applyEdit(_ actionName: String, _ ops: [ReelOp]) {
    commitEdit(actionName, ops, grouped: false)
}

/// `applyEdit` as an explicit group (`inExplicitUndoGroup`): a path outside
/// an AppKit event (the async import completion, the agent's tool calls),
/// or a rename commit that must be its own step inside one (#69).
func performGroupedEdit(_ actionName: String, _ ops: [ReelOp]) {
    commitEdit(actionName, ops, grouped: true)
}

/// Four answers (spec §5.5): `.applied` registers undo and publishes,
/// `.identity` and `.refused` are BOTH a beep and no undo step — a
/// refusal also posts `projectDocumentDidRefuse` with its sentence (spec
/// §11 CI-10) — and a throw is the core's own message. `ReelEdit` argues
/// the middle two. Only `.applied` opens the explicit group: an empty one
/// is still a step on the stack, and closing it clears redo (#59).
private func commitEdit(_ actionName: String, _ ops: [ReelOp], grouped: Bool) {
    let current = project
    do {
        switch try current.applying(addressed(ops)) {
        case .applied(let updated):
            func commit() {
                registerUndo(restoring: current, actionName: actionName)
                project = updated
                countEditChange(.changeDone)
                projectDidChange()
            }
            if grouped { inExplicitUndoGroup(commit) } else { commit() }
        case .identity:
            NSSound.beep()
        case .refused(let refusal):
            // The identity's beep and NO undo step, then the sentence.
            NSSound.beep()
            NotificationCenter.default.post(
                name: .projectDocumentDidRefuse, object: self,
                userInfo: ["refusal": refusal])
        }
    } catch {
        present(error)
    }
}

/// **Pitfall** (app/CLAUDE.md): a registration made outside an event lands
/// in the implicit per-event group AppKit never closes here, so every such
/// edit silently merges into ONE undo step. The fix is event grouping OFF
/// for the duration and a balanced explicit group, **not** forcing the
/// level to zero: that leaves an end with no begin, the checkpoint
/// `NSDocument` posts inside every save's file-coordination accessor then
/// raises `endUndoGrouping called with no matching begin`, the coordinator
/// swallows it under `autosavesInPlace`, and ⌘S and `save_project` hang
/// for good, every later file access blocking behind the unreleased claim.
private func inExplicitUndoGroup(_ body: () -> Void) {
    guard let manager = undoManager else { return body() }
    let groupsByEvent = manager.groupsByEvent
    if groupsByEvent { manager.groupsByEvent = false }
    let level = manager.groupingLevel
    manager.beginUndoGrouping()
    body()
    // Close exactly what this call opened — never a group it did not.
    while manager.groupingLevel > level { manager.endUndoGrouping() }
    if groupsByEvent { manager.groupsByEvent = true }
}

/// True while a live-edit gesture is in progress. Observers use it —
/// together with `userInfo["isLive"]` — to defer expensive refreshes
/// until the gesture ends.
var isLiveEditing: Bool { liveEditBase != nil }

/// Snapshots the current handle. The `updateLiveEdit` calls that follow
/// swap the project without touching the undo stack; `endLiveEdit` turns
/// the whole gesture into a single step.
func beginLiveEdit() {
    guard liveEditBase == nil else { return }
    liveEditBase = project
}

/// One tick of a gesture: applies `op` to the handle the gesture STARTED
/// from, not to the last tick's result, so a drag is always
/// base-plus-current-delta and the ops never compound. No undo
/// registration; the notification carries `["isLive": true]`.
func updateLiveEdit(_ op: ReelOp) {
    updateLiveEdit([op])
}

func updateLiveEdit(_ ops: [ReelOp]) {
    guard let base = liveEditBase else { return }
    guard case .applied(let updated)? = try? base.applying(addressed(ops)) else {
        // **Every answer but `.applied` is swallowed on purpose** — an
        // invalid tick, an identity and a rule's refusal alike (spec #8's
        // eighth decision). A refused tick is NORMAL here and recovers on
        // the next one; the last good frame stays. Not chatty.
        return
    }
    project = updated
    projectDidChange(isLive: true)
}

/// ONE undo step from the `beginLiveEdit` snapshot to the current handle —
/// none when no tick applied (`updateLiveEdit` swaps only on `.applied`) —
/// or, `cancelled` (Esc on the canvas, spec §11 CI-16), the snapshot put
/// back with no step and no change count; then `["isLive": false]` either
/// way, so listeners that skipped the ticks refresh once.
func endLiveEdit(_ actionName: String, cancelled: Bool = false) {
    guard let base = liveEditBase else { return }
    liveEditBase = nil
    if cancelled { project = base } else if base !== project {
        registerUndo(restoring: base, actionName: actionName)
        countEditChange(.changeDone)
    }
    projectDidChange(isLive: false)
}

/// The menu tool's group, opened by the first registration (`+UndoGroup`).
var pendingUndoGroup: PendingUndoGroup?
/// The ONE `registerUndo` call site in the app (app/CLAUDE.md).
private func registerUndo(restoring handle: ReelProject, actionName: String) {
    openPendingUndoGroup()
    undoManager?.registerUndo(withTarget: self) { document in
        document.restore(handle, actionName: actionName)
    }
    undoManager?.setActionName(actionName)
}

/// Undo/redo target. Restores a handle and registers its own inverse, so
/// the stack walks both ways from any point.
private func restore(_ restored: ReelProject, actionName: String) {
    let current = project
    registerUndo(restoring: current, actionName: actionName)
    project = restored
    if undoManager?.isRedoing == true {
        countEditChange(.changeRedone)
    } else {
        countEditChange(.changeUndone)
    }
    projectDidChange()
}

